// Light: build one item per Apify query (keyword per direct company + company-page per URN).
const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const DATE_FILTER='past-24h';   // 'past-24h' daily; 'past-week' backfill
const TOTAL=250;                 // actor auto-paginates up to this many (cap, not target)
const KW={'Lumos':['Lumos'],'Opti':['Opti IAM','Opti Identity'],'OFFROAD':['Offroad Security'],'7AI':['7AI'],'Console':['Console security'],'Oak - Identity Security OS':['Oak identity','Oak Security','oak.id']};
const comps=await helpers.httpRequest({method:'GET',url:BASE+'/competitors?select=name,linkedin_urn,type,active,keywords,definition,collision_terms&active=eq.true',headers:H,json:true});
const active=(comps||[]).filter(c=>c.active!==false);
const items=[];
for(const c of active){
  const isDirect=(c.type||'direct')!=='indirect';
  if(isDirect){ const kws=(c.keywords&&c.keywords.length)?c.keywords:(KW[c.name]||[String(c.name)]); for(const kw of kws){ items.push({json:{source:'keyword',search_input:kw,owner_company:null,body:{keyword:kw,date_filter:DATE_FILTER,sort_type:'date_posted',total_posts:TOTAL}}}); } }
  const urn=c.linkedin_urn?String(c.linkedin_urn):'';
  if(urn){ items.push({json:{source:'company_page',search_input:c.name,owner_company:c.name,body:{company_urns:urn,date_filter:DATE_FILTER,sort_type:'date_posted',total_posts:TOTAL}}}); }
}
return items;

const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
// Honest counts. queries: Build Queries ran ONCE before the SplitInBatches loop, so its
// .all() length is the true number of queries built (the old code summed the loop node
// reference, which after the loop only exposes the LAST iteration -> always '1 query').
let queries=0; try{ queries=$('Build Queries').all().length; }catch(e){}
// rows_written: raw rows that landed in the last ~15 min = this run (scrapes are daily + isolated).
let rows_written=0;
try{ const since=new Date(Date.now()-15*60000).toISOString(); const arr=await helpers.httpRequest({method:'GET',url:BASE+'/linkedin_raw?select=activity_id&scraped_at=gte.'+encodeURIComponent(since)+'&limit=2000',headers:H,json:true}); rows_written=Array.isArray(arr)?arr.length:0; }catch(e){}
const status=(queries>0)?'success':'error';
const now=new Date().toISOString();
try{ await helpers.httpRequest({method:'POST',url:BASE+'/scrape_runs',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'return=minimal'}),body:{platform:'LinkedIn',started_at:now,finished_at:now,window_to:now,rows_written:rows_written,status:status,note:'scraper v2 daily past-24h ('+queries+' queries)'},json:true}); }catch(e){}
return [{json:{scraperDone:true,queries,rows_written,status}}];

// One query's posts (<=250), transient. Flatten + upsert to linkedin_raw. Metadata from the current batch item (batchSize 1).
const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const meta=$('Loop Queries').first().json||{};
const source=meta.source||'keyword'; const search_input=meta.search_input||null; const owner=meta.owner_company||null;
function flatten(t){ if(!t||!t.activity_id) return null; const stats=t.stats||{}; const article=(t.content&&t.content.article)?t.content.article:{}; return {activity_id:t.activity_id,post_url:t.post_url||'',text:t.text||'',full_urn:t.full_urn||'',author:t.author||{},totalReactions:stats.total_reactions||0,comments:stats.comments||0,reshares:stats.shares||0,posted_at:(t.posted_at&&t.posted_at.date)?t.posted_at.date:null,hashtags:t.hashtags||[],content:t.content||{},is_reshare:!!t.is_reshare,metadata:t.metadata||{},search_input:search_input,title:article.title||'',imageURL:article.thumbnail_url||'',source:source}; }
const seen={}; const rows=[];
for(const item of $input.all()){ const t=item.json||{}; const f=flatten(t); if(f&&!seen[f.activity_id]){ seen[f.activity_id]=1; rows.push({activity_id:f.activity_id,raw:f,source:source,search_input:search_input,owner_company:owner,status:'pending'}); } }
let n=0;
if(rows.length){ try{ await helpers.httpRequest({method:'POST',url:BASE+'/linkedin_raw?on_conflict=activity_id',headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'resolution=merge-duplicates,return=minimal'}),body:rows,json:true}); n=rows.length; }catch(e){ return [{json:{query:search_input,error:String(e&&e.message||e)}}]; } }
return [{json:{query:search_input,source:source,upserted:n}}];
